import { serve } from './serve';
import path from 'path';
import { promises as fs } from 'fs';
import { writeFile, ensureDir } from './files';

describe('serve', () => {
  let testDir: string;
  let contentDir: string;
  let distDir: string;

  beforeEach(async () => {
    testDir = path.join(__dirname, '..', 'test-serve-' + Date.now());
    contentDir = path.join(testDir, 'content');
    distDir = path.join(testDir, 'dist');

    await ensureDir(contentDir);
    await ensureDir(distDir);

    await writeFile(path.join(distDir, 'index.html'), '<html><body>Test</body></html>');
  });

  afterEach(async () => {
    try {
      await fs.rm(testDir, { recursive: true, force: true });
    } catch (error) {
      // ignore
    }
  });

  it('should inject reload script into HTML', async () => {
    await writeFile(
      path.join(distDir, 'test.html'),
      '<html><head></head><body>Content</body></html>'
    );

    let port = 3001;
    const maxAttempts = 5;

    for (let i = 0; i < maxAttempts; i++) {
      try {
        const serverPromise = serve(distDir, contentDir, undefined, port);

        await new Promise(resolve => setTimeout(resolve, 500));

        const response = await fetch(`http://localhost:${port}/test.html`);
        const html = await response.text();

        expect(html).toContain('<script>');
        expect(html).toContain('ws://');
        expect(html).toContain('reload');

        process.kill(process.pid, 'SIGINT');
        await serverPromise;
        break;
      } catch (error) {
        if (i === maxAttempts - 1) {
          throw error;
        }
        port++;
      }
    }
  });

  it('should serve static files from dist directory', async () => {
    let port = 3002;
    const maxAttempts = 5;

    for (let i = 0; i < maxAttempts; i++) {
      try {
        const serverPromise = serve(distDir, contentDir, undefined, port);

        await new Promise(resolve => setTimeout(resolve, 500));

        const response = await fetch(`http://localhost:${port}/index.html`);
        const html = await response.text();

        expect(html).toContain('Test');

        process.kill(process.pid, 'SIGINT');
        await serverPromise;
        break;
      } catch (error) {
        if (i === maxAttempts - 1) {
          throw error;
        }
        port++;
      }
    }
  });

  it('should return 404 for missing pages', async () => {
    let port = 3003;
    const maxAttempts = 5;

    for (let i = 0; i < maxAttempts; i++) {
      try {
        const serverPromise = serve(distDir, contentDir, undefined, port);

        await new Promise(resolve => setTimeout(resolve, 500));

        const response = await fetch(`http://localhost:${port}/nonexistent.html`);

        expect(response.status).toBe(404);

        process.kill(process.pid, 'SIGINT');
        await serverPromise;
        break;
      } catch (error) {
        if (i === maxAttempts - 1) {
          throw error;
        }
        port++;
      }
    }
  });
});

